import fs from 'node:fs'
import path from 'node:path'
import { legacyPathFor, readFrontMatter, type PageMeta } from './paths'

/**
 * 侧边栏：从内容目录现场生成，不手写。
 *
 * 旧站点用的是 `sidebars.ts` + `autogenerated`，顶层顺序靠一张手写表，
 * 目录内部靠 `sidebar_position`。这里保留同一套语义，但**不再需要维护
 * 第二份文件**：新增一篇带 `sidebar_position` 的 md 就会自动出现在正确位置。
 *
 * 顶层顺序照抄旧 `sidebars.ts`（那张表是刻意的，不是按目录名排的）。
 */
export interface SidebarItem {
  text: string
  link?: string
  collapsible?: boolean
  expanded?: boolean
  children?: SidebarItem[]
}

/** `/docs` 的顶层顺序（对应旧 sidebars.ts） */
const DOC_TOP_ORDER = [
  'intro',
  '前端',
  '后端',
  '嵌入式',
  '计算机基础',
  'Java与计算机基础',
  'Python与计算机基础',
  '机器学习',
  'Agent',
  'Prompt收集',
  '项目',
  '软件配置',
  '读书笔记',
]

/** `/code-training` 的顶层顺序（对应旧 code-training/sidebars.ts） */
const TRAINING_TOP_ORDER = [
  'intro',
  'problems',
  'machine-learning',
  'data-structures',
  'patterns',
  'review',
  'resources',
]

/** 顶层目录的中文名（其余目录用 `_category_.json` 的 label，再退回目录名） */
const DIR_LABELS: Record<string, string> = {
  problems: '题库',
  'machine-learning': '机器学习',
  'data-structures': '数据结构',
  patterns: '算法模式',
  review: '复习系统',
  codefun2000: 'CodeFun2000',
  leetcode: 'LeetCode',
  nowcoder: 'Nowcoder',
  sf: 'Shoppee 笔试题',
  shoppee: 'Shoppee',
  misc: '其它',
}

const collator = new Intl.Collator('zh-Hans-CN', { numeric: true })

function dirLabel(dir: string, fallback: string): string {
  const categoryFile = path.join(dir, '_category_.json')
  if (fs.existsSync(categoryFile)) {
    try {
      const parsed = JSON.parse(fs.readFileSync(categoryFile, 'utf8')) as {
        label?: string
      }
      if (parsed.label) return parsed.label
    } catch {
      /* 忽略坏掉的 _category_.json */
    }
  }
  return DIR_LABELS[fallback] ?? fallback
}

function dirPosition(dir: string): number | undefined {
  const categoryFile = path.join(dir, '_category_.json')
  if (!fs.existsSync(categoryFile)) return undefined
  try {
    const parsed = JSON.parse(fs.readFileSync(categoryFile, 'utf8')) as {
      position?: number
    }
    return typeof parsed.position === 'number' ? parsed.position : undefined
  } catch {
    return undefined
  }
}

interface Entry {
  order: number
  item: SidebarItem
}

function fileItem(
  sourceDir: string,
  filePath: string,
  meta: PageMeta,
  name: string,
  topOrder?: string[],
): Entry {
  const link = legacyPathFor(sourceDir, filePath, meta) ?? undefined
  const text =
    meta.sidebar_label ??
    (name.replace(/\.(md|mdx)$/, '') === 'intro'
      ? '首页'
      : (meta.title ?? name.replace(/\.(md|mdx)$/, '')))
  const byName = topOrder?.indexOf(name.replace(/\.(md|mdx)$/, '')) ?? -1
  const order =
    byName !== -1
      ? byName
      : typeof meta.sidebar_position === 'number'
        ? meta.sidebar_position
        : typeof meta.order === 'number'
          ? meta.order
          : 9999
  return { order, item: { text, link } }
}

function walkDir(
  dir: string,
  sourceDir: string,
  depth: number,
  topOrder?: string[],
): SidebarItem[] {
  const dirents = fs.readdirSync(dir, { withFileTypes: true })
  const entries: Entry[] = []
  const dirs: Array<{ name: string; path: string }> = []

  for (const dirent of dirents) {
    const full = path.join(dir, dirent.name)
    if (dirent.isDirectory()) {
      if (dirent.name.startsWith('.') || dirent.name.startsWith('_')) continue
      if (dirent.name === 'node_modules') continue
      dirs.push({ name: dirent.name, path: full })
      continue
    }
    if (!/\.(md|mdx)$/.test(dirent.name)) continue
    if (dirent.name.startsWith('_') || dirent.name.startsWith('.')) continue

    const meta = readFrontMatter(full)
    // 站点首页不重复出现在侧边栏
    if (legacyPathFor(sourceDir, full, meta) === '/') continue
    entries.push(
      fileItem(
        sourceDir,
        full,
        meta,
        dirent.name,
        depth === 0 ? topOrder : undefined,
      ),
    )
  }

  for (const sub of dirs) {
    const children = walkDir(sub.path, sourceDir, depth + 1)
    if (children.length === 0) continue
    const guide = path.join(sub.path, '导读.md')
    const meta = readFrontMatter(guide) as PageMeta
    const byName = topOrder?.indexOf(sub.name) ?? -1
    entries.push({
      order:
        byName !== -1
          ? byName
          : (dirPosition(sub.path) ?? 9999),
      item: {
        text: dirLabel(sub.path, sub.name),
        collapsible: true,
        expanded: false,
        ...(fs.existsSync(guide)
          ? { link: legacyPathFor(sourceDir, guide, meta) ?? undefined }
          : {}),
        children,
      },
    })
  }

  entries.sort((a, b) => {
    if (a.order !== b.order) return a.order - b.order
    return collator.compare(a.item.text, b.item.text)
  })

  return entries.map((entry) => entry.item)
}

export function buildSidebar(sourceDir: string, contentDir: string, topOrder: string[]): SidebarItem[] {
  return walkDir(contentDir, sourceDir, 0, topOrder)
}

export function docsSidebar(sourceDir: string): SidebarItem[] {
  return buildSidebar(sourceDir, path.join(sourceDir, 'docs'), DOC_TOP_ORDER)
}

export function trainingSidebar(sourceDir: string): SidebarItem[] {
  return buildSidebar(
    sourceDir,
    path.join(sourceDir, 'code-training/docs'),
    TRAINING_TOP_ORDER,
  )
}
